// A deliberately small, dependency-free linker for this fixed ES-module graph.
import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
const files = [
  'defaults',
  'policy',
  'tokens',
  'routes',
  'results',
  'reports',
  'oidc',
  'github',
  'vast',
  'ledger',
  'offers',
  'onstart',
  'sanitize',
  'index',
];
const base = new URL('./', import.meta.url);
let output = '// Generated by bundle.js; edit src/, not this file.\n';
for (const name of files) {
  let text = await readFile(new URL('src/' + name + '.js', base), 'utf8');
  if (name === 'defaults')
    text =
      'const DEFAULTS=Object.freeze(' +
      JSON.stringify(JSON.parse(await readFile(new URL('defaults.json', base), 'utf8')), null, 2) +
      ');\n';
  const imports = [...text.matchAll(/^import .* from ['"]\.\/([^'"]+)['"];$/gm)];
  for (const match of imports) {
    const dependency = match[1].replace(/\.js$/, '');
    if (files.indexOf(dependency) < 0 || files.indexOf(dependency) >= files.indexOf(name))
      throw Error('Unexpected dependency order');
  }
  text = text.replace(/^import .* from ['"]\.\/[^'"]+['"];\n/gm, '');
  if (/^import /m.test(text.split(/^export /m)[0])) throw Error('Unsupported import: ' + name);
  if (name !== 'index') text = text.replace(/^export /gm, '');
  output += '\n// ' + name + '.js\n' + text;
}
await mkdir(new URL('dist/', base), { recursive: true });
const destination = new URL('dist/worker.js', base);
const formatted = spawnSync(
  'npx',
  [
    '--yes',
    'prettier@3.6.2',
    '--config',
    fileURLToPath(new URL('.prettierrc.json', base)),
    '--stdin-filepath',
    'worker.js',
  ],
  { input: output, encoding: 'utf8' },
);
if (formatted.status !== 0) throw Error(formatted.stderr);
output = formatted.stdout;
await writeFile(destination, output);
const check = spawnSync(process.execPath, ['--check', fileURLToPath(destination)], {
  encoding: 'utf8',
});
if (check.status !== 0) throw Error(check.stderr);
await writeFile(
  new URL('dist/deployment.json', base),
  JSON.stringify(
    {
      protocol_version: 4,
      worker_version: 'v5',
      bundle_sha256: createHash('sha256').update(output).digest('hex'),
    },
    null,
    2,
  ) + '\n',
);
console.log('Built dist/worker.js (' + Buffer.byteLength(output) + ' bytes)');
